function findPropertyDescriptor(target: object, prop: string): PropertyDescriptor | undefined {
 let obj: object | null = target;
 while (obj) {
   const desc = Object.getOwnPropertyDescriptor(obj, prop);
   if (desc) return desc;
   obj = Object.getPrototypeOf(obj);
 }
 return undefined;
}
```

