const stateCache = new WeakMap<GeospatialCamera, ModeState>();

export function useModeLimits(camera: GeospatialCamera, limits: GeospatialLimits): void {
  let state = stateCache.get(camera);
  if (!state) {
    state = { limits };
    stateCache.set(camera, state);
    installCameraInterceptors(camera, state);
  } else {
    state.limits = limits;
  }
  camera.limits = limits;
  enforceCurrentPose(camera, state);
}
```

