import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

const TWO_PI = Math.PI * 2;
const stateByCamera = new WeakMap<GeospatialCamera, ModeLimitsState>();

interface ModeLimitsState {
  limits: GeospatialLimits;
  installed: boolean;
}

function findPropertyDescriptor(target: object, key: string): PropertyDescriptor | undefined {
  let current: object | null = target;
  while (current) {
    const descriptor = Object.getOwnPropertyDescriptor(current, key);
    if (descriptor) return descriptor;
    current = Object.getPrototypeOf(current);
  }
  return undefined;
}

function clampRadius(value: number, limits: GeospatialLimits): number {
  if (!Number.isFinite(value)) {
    return Number.isFinite(limits.radiusMin) ? limits.radiusMin : 0;
  }
  const min = Number.isFinite(limits.radiusMin) ? limits.radiusMin : -Infinity;
  const max = Number.isFinite(limits.radiusMax) ? limits.radiusMax : Infinity;
  const lower = Math.min(min, max);
  const upper = Math.max(min, max);
  if (value < lower) return lower;
  if (value > upper) return upper;
  return value;
}

function normalizeYaw(angle: number): number {
  if (!Number.isFinite(angle)) return -Math.PI;
  let a = (angle + Math.PI) % TWO_PI;
  if (a < 0) a += TWO_PI;
  return a - Math.PI;
}

function clampYaw(value: number, limits: GeospatialLimits): number {
  let v = normalizeYaw(value);
  const min = limits.yawMin;
  const max = limits.yawMax;
  if (!Number.isFinite(min) || !Number.isFinite(max)) return v;
  if (min === max) return normalizeYaw(min);
  if (min <= max) {
    if (v < min) return min;
    if (v > max) return max;
    return v;
  }
  // wrap-around range: [min, PI] ∪ [-PI, max]
  if (v >= min || v <= max) return v;
  const distanceToMin = Math.abs(v - min);
  const distanceToMax = Math.abs(v - max);
  return distanceToMin <= distanceToMax ? min : max;
}

function enforceCurrentPose(camera: GeospatialCamera, state: ModeLimitsState): void {
  const yaw = clampYaw(camera.yaw, state.limits);
  if (yaw !== camera.yaw) camera.yaw = yaw; // but camera.yaw getter may return normalized/clamped; if original raw changed? hmm. Could always write.
  const radius = clampRadius(camera.radius, state.limits);
  if (radius !== camera.radius) camera.radius = radius;
}
```

