Implementation of installNumberProperty:

```
function installNumberProperty(camera: GeospatialCamera, prop: 'yaw' | 'radius', state: ModeLimitsState): void {
  const descriptor = findPropertyDescriptor(camera, prop);
  const originalGet = descriptor?.get as (() => number) | undefined;
  const originalSet = descriptor?.set as ((value: number) => void) | undefined;
  const isData = !originalGet && !originalSet;
  let stored: number | undefined;
  if (isData) {
    stored = descriptor?.value as number | undefined;
    if (stored === undefined) {
      stored = prop === 'yaw' ? 0 : state.limits.radiusMin;
    }
  } else if (originalGet) {
    try { stored = originalGet.call(camera); } catch { stored = undefined; }
  }
  const clamp = prop === 'yaw' ? clampYaw : clampRadius;
  const getter = () => {
    const raw = originalGet ? originalGet.call(camera) : stored ?? (prop === 'yaw' ? 0 : state.limits.radiusMin);
    return clamp(raw, state.limits);
  };
  const setter = (value: number) => {
    const next = clamp(value, state.limits);
    if (originalSet) originalSet.call(camera, next);
    else stored = next;
  };
  Object.defineProperty(camera, prop, {
    configurable: true,
    enumerable: descriptor?.enumerable ?? true,
    get: getter,
    set: setter,
  });
}
```

