function clampYaw(value, limits) {
  const min = limits.yawMin; const max = limits.yawMax;
  if (!Number.isFinite(min) || !Number.isFinite(max)) return normalizeYaw(value);
  const rawSpan = Math.abs(max - min);
  if (rawSpan >= TWO_PI - YAW_EPSILON) return normalizeYaw(value);
  const minNorm = normalizeYaw(min); const maxNorm = normalizeYaw(max);
  if (Math.abs(minNorm - maxNorm) < YAW_EPSILON) return minNorm;
  const current = normalizeYaw(value);
  if (minNorm <= maxNorm) {
    if (current >= minNorm && current <= maxNorm) return current;
  } else {
    if (current >= minNorm || current <= maxNorm) return current;
  }
  return angularDistance(current, minNorm) <= angularDistance(current, maxNorm) ? minNorm : maxNorm;
}
```

