import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

const TWO_PI = Math.PI * 2;
const YAW_EPSILON = 1e-12;

interface ModeLimitsState {
  limits: GeospatialLimits;
  getRawYaw?: () => number;
  getRawRadius?: () => number;
}

const modeLimitsState = new WeakMap<GeospatialCamera, ModeLimitsState>();

function findPropertyDescriptor(target: object, key: string): PropertyDescriptor | undefined {
  let current: object | null = target;
  while (current) {
    const descriptor = Object.getOwnPropertyDescriptor(current, key);
    if (descriptor) return descriptor;
    current = Object.getPrototypeOf(current) as object | null;
  }
  return undefined;
}

function normalizeYaw(angle: number): number {
  if (!Number.isFinite(angle)) return -Math.PI;
  let normalized = (angle + Math.PI) % TWO_PI;
  if (normalized < 0) normalized += TWO_PI;
  return normalized - Math.PI;
}

function angularDistance(a: number, b: number): number {
  return Math.abs(normalizeYaw(a - b));
}

function clampYaw(value: number, limits: GeospatialLimits): number {
  const min = limits.yawMin;
  const max = limits.yawMax;
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    return normalizeYaw(value);
  }

  const rawSpan = Math.abs(max - min);
  if (rawSpan >= TWO_PI - YAW_EPSILON) {
    return normalizeYaw(value);
  }

  const minNorm = normalizeYaw(min);
  const maxNorm = normalizeYaw(max);

  if (Math.abs(minNorm - maxNorm) < YAW_EPSILON) {
    return minNorm;
  }

  const current = normalizeYaw(value);

  if (minNorm <= maxNorm) {
    if (current >= minNorm && current <= maxNorm) {
      return current;
    }
  } else {
    if (current >= minNorm || current <= maxNorm) {
      return current;
    }
  }

  return angularDistance(current, minNorm) <= angularDistance(current, maxNorm) ? minNorm : maxNorm;
}

function clampRadius(value: number, limits: GeospatialLimits): number {
  if (!Number.isFinite(value)) {
    if (Number.isFinite(limits.radiusMin)) return limits.radiusMin;
    if (Number.isFinite(limits.radiusMax)) return limits.radiusMax;
    return 0;
  }

  const min = Number.isFinite(limits.radiusMin) ? limits.radiusMin : -Infinity;
  const max = Number.isFinite(limits.radiusMax) ? limits.radiusMax : Infinity;
  const lower = Math.min(min, max);
  const upper = Math.max(min, max);

  if (value < lower) return lower;
  if (value > upper) return upper;
  return value;
}

function needsEnforcement(raw: number, clamped: number, hasRawGetter: boolean): boolean {
  return !hasRawGetter || raw !== clamped || (!Number.isFinite(raw) && Number.isFinite(clamped));
}

function installNumberProperty(
  camera: GeospatialCamera,
  key: "yaw" | "radius",
  state: ModeLimitsState,
  initialValue: number
): void {
  const descriptor = findPropertyDescriptor(camera, key);
  const originalGet = descriptor?.get as (() => number) | undefined;
  const originalSet = descriptor?.set as ((value: number) => void) | undefined;
  const clamp = key === "yaw" ? clampYaw : clampRadius;

  let stored = initialValue;
  if (typeof stored !== "number") {
    stored = key === "yaw" ? 0 : (Number.isFinite(state.limits.radiusMin) ? state.limits.radiusMin : 0);
  }
  if (descriptor && "value" in descriptor) {
    const descriptorValue = descriptor.value as number | undefined;
    if (typeof descriptorValue === "number") {
      stored = descriptorValue;
    } else {
      stored = key === "yaw" ? 0 : (Number.isFinite(state.limits.radiusMin) ? state.limits.radiusMin : 0);
    }
  }

  const canReadOriginal = !!originalGet && !!originalSet;
  const rawGetter = canReadOriginal ? () => originalGet!.call(camera) : () => stored;
  if (key === "yaw") {
    state.getRawYaw = rawGetter;
  } else {
    state.getRawRadius = rawGetter;
  }

  Object.defineProperty(camera, key, {
    configurable: true,
    enumerable: descriptor?.enumerable ?? true,
    get() {
      const raw = canReadOriginal ? originalGet!.call(camera) : stored;
      return clamp(raw, state.limits);
    },
    set(value: number) {
      const next = clamp(value, state.limits);
      if (originalSet) {
        originalSet.call(camera, next);
      }
      stored = next;
    },
  });
}

function installSetOrientation(camera: GeospatialCamera, state: ModeLimitsState): void {
  const original = camera._setOrientation;
  if (typeof original !== "function") return;

  type CenterArg = Parameters<GeospatialCamera["_setOrientation"]>[3];
  const wrapper = (yaw: number, pitch: number, radius: number, center: CenterArg) => {
    original.call(
      camera,
      clampYaw(yaw, state.limits),
      pitch,
      clampRadius(radius, state.limits),
      center
    );
  };

  Object.defineProperty(camera, "_setOrientation", {
    configurable: true,
    writable: true,
    value: wrapper,
  });
}

function installInterceptors(camera: GeospatialCamera, state: ModeLimitsState): void {
  const initialYaw = camera.yaw;
  const initialRadius = camera.radius;
  installNumberProperty(camera, "yaw", state, initialYaw);
  installNumberProperty(camera, "radius", state, initialRadius);
  installSetOrientation(camera, state);
}

function enforceCurrentPose(camera: GeospatialCamera, state: ModeLimitsState): void {
  const hasRawRadius = !!state.getRawRadius;
  const rawRadius = hasRawRadius ? state.getRawRadius!() : camera.radius;
  const clampedRadius = clampRadius(rawRadius, state.limits);
  if (needsEnforcement(rawRadius, clampedRadius, hasRawRadius)) {
